from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test-order-1")
async def test_order_1(file: UploadFile = File(), token: str = Form()):
    return {"file": file.filename, "token": token}

@app.post("/test-order-2")
async def test_order_2(token: str = Form(), file: UploadFile = File()):
    return {"file": file.filename, "token": token}

@app.post("/test-multiple-files")
async def test_multiple_files(file1: UploadFile = File(), file2: UploadFile = File(), token: str = Form()):
    return {"file1": file1.filename, "file2": file2.filename, "token": token}

client = TestClient(app)

def test_order_1():
    with open("test_file.txt", "wb") as f:
        f.write(b"content")

    with open("test_file.txt", "rb") as f:
        response = client.post(
            "/test-order-1",
            files={"file": ("test_file.txt", f, "text/plain")},
            data={"token": "foo"}
        )
    assert response.status_code == 200
    assert response.json() == {"file": "test_file.txt", "token": "foo"}

def test_order_2():
    with open("test_file.txt", "wb") as f:
        f.write(b"content")

    with open("test_file.txt", "rb") as f:
        response = client.post(
            "/test-order-2",
            files={"file": ("test_file.txt", f, "text/plain")},
            data={"token": "foo"}
        )
    assert response.status_code == 200
    assert response.json() == {"file": "test_file.txt", "token": "foo"}

def test_multiple_files():
    with open("test_file1.txt", "wb") as f1:
        f1.write(b"content1")
    with open("test_file2.txt", "wb") as f2:
        f2.write(b"content2")

    with open("test_file1.txt", "rb") as f1, open("test_file2.txt", "rb") as f2:
        response = client.post(
            "/test-multiple-files",
            files={"file1": ("test_file1.txt", f1, "text/plain"), "file2": ("test_file2.txt", f2, "text/plain")},
            data={"token": "foo"}
        )
    assert response.status_code == 200
    assert response.json() == {"file1": "test_file1.txt", "file2": "test_file2.txt", "token": "foo"}

